import java.util.InputMismatchException;
import java.util.Scanner;

/**
 * Simple utility to add two numbers entered by the user.
 */
public class AddTwoNumbers {

    /**
     * Adds two integers.
     *
     * @param a first operand
     * @param b second operand
     * @return the sum of a and b
     */
    public static int add(int a, int b) {
        return a + b;
    }

    /**
     * Reads an integer from the scanner, reprompting until a valid value is entered.
     *
     * @param scanner the scanner to read from
     * @param prompt  message displayed to the user
     * @return a valid integer entered by the user
     */
    private static int readInt(Scanner scanner, String prompt) {
        while (true) {
            System.out.print(prompt);
            try {
                return scanner.nextInt();
            } catch (InputMismatchException e) {
                System.out.println("Invalid input. Please enter a whole number.");
                scanner.nextLine(); // discard the invalid token
            }
        }
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int firstNumber = readInt(scanner, "Enter the first number: ");
            int secondNumber = readInt(scanner, "Enter the second number: ");

            int sum = add(firstNumber, secondNumber);
            System.out.println("The sum is: " + sum);
        }
    }
}
```

